-- Archive conflicting progress before removing it from active tables, atomically.
-- Archives remain local and are included in logical profile backups.
CREATE TRIGGER traveler_profile_cleanup AFTER UPDATE OF traveler_gender ON profiles
BEGIN
  INSERT INTO app_settings(key,value,updated_at)
  SELECT 'traveler_archive:' || NEW.id,
    json_insert(COALESCE((SELECT value FROM app_settings WHERE key = 'traveler_archive:' || NEW.id),'[]'), '$[#]',
      json_object('archivedAt',CURRENT_TIMESTAMP,'characters',(SELECT json_group_array(json_object('id',id,'profile_id',profile_id,'character_id',character_id,'owned',owned,'constellation',constellation,'level',level,'ascension',ascension,'friendship',friendship,'notes',notes,'created_at',created_at,'updated_at',updated_at,'combat_stats',combat_stats)) FROM account_characters WHERE profile_id = NEW.id AND (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND (NEW.traveler_gender IS NULL OR (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) <> NEW.traveler_gender)),
        'builds',(SELECT json_group_array(json_object('id',id,'profile_id',profile_id,'character_id',character_id,'status',status,'account_weapon_id',account_weapon_id,'weapon_target_level',weapon_target_level,'character_target_level',character_target_level,'normal_attack_level',normal_attack_level,'normal_attack_target',normal_attack_target,'elemental_skill_level',elemental_skill_level,'elemental_skill_target',elemental_skill_target,'elemental_burst_level',elemental_burst_level,'elemental_burst_target',elemental_burst_target,'notes',notes,'created_at',created_at,'updated_at',updated_at,'farm_enabled',farm_enabled,'character_target_ascension',character_target_ascension,'weapon_target_ascension',weapon_target_ascension,'farm_priority',farm_priority,'farm_status',farm_status,'planned_weapon_id',planned_weapon_id)) FROM character_builds WHERE profile_id = NEW.id AND (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND (NEW.traveler_gender IS NULL OR (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) <> NEW.traveler_gender)),'slots',(SELECT json_group_array(json_object('id',id,'build_id',build_id,'slot_key',slot_key,'set_id',set_id,'main_stat',main_stat,'level',level,'target_level',target_level,'is_equipped',is_equipped,'rarity',rarity,'notes',notes,'created_at',created_at,'updated_at',updated_at,'substats',substats)) FROM build_artifact_slots WHERE build_id IN (SELECT id FROM character_builds WHERE profile_id = NEW.id AND (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND (NEW.traveler_gender IS NULL OR (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) <> NEW.traveler_gender))),'weapons',(SELECT json_group_array(json_object('id',id,'profile_id',profile_id,'weapon_id',weapon_id,'instance_no',instance_no,'level',level,'ascension',ascension,'refinement',refinement,'equipped_character_id',equipped_character_id,'favorite',favorite,'notes',notes,'created_at',created_at,'updated_at',updated_at)) FROM account_weapons WHERE profile_id = NEW.id AND (CASE WHEN equipped_character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN equipped_character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND (NEW.traveler_gender IS NULL OR (CASE WHEN equipped_character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN equipped_character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) <> NEW.traveler_gender)))),CURRENT_TIMESTAMP
  WHERE EXISTS(SELECT 1 FROM account_characters WHERE profile_id = NEW.id AND (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND (NEW.traveler_gender IS NULL OR (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) <> NEW.traveler_gender)) OR EXISTS(SELECT 1 FROM character_builds WHERE profile_id = NEW.id AND (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND (NEW.traveler_gender IS NULL OR (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) <> NEW.traveler_gender)) OR EXISTS(SELECT 1 FROM account_weapons WHERE profile_id = NEW.id AND (CASE WHEN equipped_character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN equipped_character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND (NEW.traveler_gender IS NULL OR (CASE WHEN equipped_character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN equipped_character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) <> NEW.traveler_gender))
  ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at;
  DELETE FROM build_artifact_slots WHERE build_id IN (SELECT id FROM character_builds WHERE profile_id = NEW.id AND (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND (NEW.traveler_gender IS NULL OR (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) <> NEW.traveler_gender));
  DELETE FROM character_builds WHERE profile_id = NEW.id AND (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND (NEW.traveler_gender IS NULL OR (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) <> NEW.traveler_gender);
  DELETE FROM account_characters WHERE profile_id = NEW.id AND (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND (NEW.traveler_gender IS NULL OR (CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) <> NEW.traveler_gender);
  UPDATE account_weapons SET equipped_character_id=NULL WHERE profile_id = NEW.id AND (CASE WHEN equipped_character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN equipped_character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND (NEW.traveler_gender IS NULL OR (CASE WHEN equipped_character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN equipped_character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) <> NEW.traveler_gender);
  UPDATE profiles SET avatar_character_id=CASE WHEN NEW.traveler_gender IS NULL THEN NULL ELSE 'character_' || NEW.traveler_gender END WHERE id=NEW.id AND (CASE WHEN avatar_character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN avatar_character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND (NEW.traveler_gender IS NULL OR (CASE WHEN avatar_character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN avatar_character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) <> NEW.traveler_gender);
END;

-- Unambiguous legacy registration determines an unset choice. With both and no
-- configured choice, retain both in the archive instead of assigning one arbitrarily.
UPDATE profiles SET traveler_gender=(SELECT MIN(gender) FROM (
 SELECT profile_id, CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END AS gender FROM account_characters
 UNION SELECT profile_id, CASE WHEN character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END AS gender FROM character_builds
) WHERE profile_id=profiles.id AND gender IS NOT NULL HAVING COUNT(DISTINCT gender)=1)
WHERE traveler_gender IS NULL;
UPDATE profiles SET traveler_gender=traveler_gender WHERE traveler_gender IS NOT NULL;

CREATE TRIGGER traveler_guard_account_characters_insert BEFORE INSERT ON account_characters
WHEN (CASE WHEN NEW.character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN NEW.character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL AND EXISTS(SELECT 1 FROM profiles WHERE id=NEW.profile_id AND traveler_gender IS NOT NULL AND traveler_gender <> (CASE WHEN NEW.character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN NEW.character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END))
BEGIN SELECT RAISE(ABORT,'Protagonista incompatível com o perfil. Altere a escolha nas configurações.'); END;
CREATE TRIGGER traveler_select_account_characters_insert AFTER INSERT ON account_characters
WHEN (CASE WHEN NEW.character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN NEW.character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) IS NOT NULL
BEGIN UPDATE profiles SET traveler_gender=(CASE WHEN NEW.character_id IN ('character_aether','char_aether','aether','10000005') THEN 'aether' WHEN NEW.character_id IN ('character_lumine','char_lumine','lumine','10000007') THEN 'lumine' END) WHERE id=NEW.profile_id AND traveler_gender IS NULL; END;

